export async function analyze(ctx){
 const s=ctx.sources.find(s=>s.id==='1c3f83a2-fb7c-4a76-91f3-2175eefe7a5b');
 if(!s)throw new Error('Required source is unavailable.');
 const ix=id=>s.columns.findIndex(c=>c.id===id);const d=ix('c0'),v=ix('c1'),w=ix('c3');if([d,v,w].some(i=>i<0))throw new Error('Required columns are unavailable.');
 const search=String(ctx.params.search||'').toLowerCase(),workspace=String(ctx.params.workspace||''),mode=ctx.params.aggregation==='average'?'average':'sum';
 const groups=new Map();let included=0,filtered=0,invalid=0,future=0;const today=new Date().toISOString().slice(0,10);
 for(const r of s.rows){const date=r[d]||'',ws=r[w]||'',raw=(r[v]||'').trim();if(!date.toLowerCase().includes(search)||(workspace!==''&&ws!==workspace)){filtered++;continue;}
 const stamp=Date.parse(date+'T00:00:00Z'),n=Number(raw);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(stamp)||new Date(stamp).toISOString().slice(0,10)!==date||raw===''||!Number.isFinite(n)||n<0||!Number.isInteger(n)){invalid++;continue;}
 const g=groups.get(date)||{sum:0,n:0,ws:new Set()};g.sum+=n;g.n++;g.ws.add(ws);groups.set(date,g);included++;if(date>today)future++;
 }
 const rows=[...groups].sort(([a],[b])=>a.localeCompare(b)).map(([date,g])=>[date,mode==='average'?g.sum/g.n:g.sum,g.n,[...g.ws].sort().join(', ')]);
 const warnings=['Source-reported active_users; distinct-user methodology and refresh time are unknown.','Workspace coverage may change by date. Sums can double-count people across workspaces; averages describe records, not overall DAU.','Missing days are not zero-filled; lines connect observed dates. Current-day and latest-period completeness are unknown.'];
 if(future)warnings.push(future+' future-dated records retained relative to '+today+' (UTC); these are not verified observations.');if(invalid)warnings.push(invalid+' matching records excluded for invalid dates or active_users.');
 return {datasets:{daily:{columns:['date','active_users','records','workspace_ids'],rows,methodId:'daily',units:'users'},workspaces:{columns:['workspace_id'],rows:[...new Set(s.rows.map(r=>r[w]||'').filter(Boolean))].sort().map(x=>[x]),methodId:'daily'},provenance:{columns:['revision','aggregation','filtered_rows','invalid_rows','as_of_utc'],rows:[[String(s.revision||'Unknown'),mode,filtered,invalid,today]],methodId:'daily'}},inputRows:s.rows.length,includedRows:included,excludedRows:filtered+invalid,warnings,checks:[]};
}

