import React from 'react';
import {LineChart,ScaleTypes} from '@carbon/charts-react';
import {TextInput,Select,SelectItem,Table,TableHead,TableRow,TableHeader,TableBody,TableCell} from '@carbon/react';
import {carbon} from '@folio/sdk';
export function View({result,params,setParams}){
 if(!result)return <p role="status">Loading usage data…</p>;
 if(!result.datasets?.daily)return <p role="alert">Usage data is unavailable.</p>;
 const t=result.datasets.daily,p=result.datasets.provenance.rows[0],average=p[1]==='average';
 const data=t.rows.map(r=>({group:average?'Average reported active users':'Reported active users',date:new Date(String(r[0])+'T00:00:00Z'),value:r[1]}));
 const formatDate=x=>new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',timeZone:'UTC'}).format(new Date(x));
 const options={...carbon.chartOptions,theme:'white',height:'360px',axes:{bottom:{mapsTo:'date',scaleType:ScaleTypes.TIME,title:'Date (UTC display)',ticks:{formatter:formatDate}},left:{mapsTo:'value',scaleType:ScaleTypes.LINEAR,title:average?'Users (record average)':'Users (sum)',includeZero:true}},legend:{enabled:false},curve:'curveLinear',accessibility:{svgAriaLabel:'Daily source-reported active users in users. Workspace coverage may vary; see the data table and caveats.'}};
 return <section aria-label="Daily usage exploration" style={{display:'grid',gap:'var(--cds-spacing-05)'}}>
 <div style={{display:'flex',flexWrap:'wrap',gap:'var(--cds-spacing-05)',alignItems:'end'}}>
 <TextInput id="usage-date-filter" labelText="Filter dates" helperText="Matches source YYYY-MM-DD dates" value={String(params.search||'')} onChange={e=>setParams({search:e.target.value})}/>
 <Select id="usage-workspace" labelText="Workspace" value={String(params.workspace||'')} onChange={e=>setParams({workspace:e.target.value})}><SelectItem value="" text="All workspaces"/>{result.datasets.workspaces.rows.map(r=><SelectItem key={String(r[0])} value={String(r[0])} text={String(r[0])}/>)}</Select>
 <Select id="usage-aggregation" labelText="Daily aggregation" value={String(p[1])} onChange={e=>setParams({aggregation:e.target.value})}><SelectItem value="sum" text="Sum of reported users"/><SelectItem value="average" text="Average per record"/></Select>
 </div>
 <p>{result.includedRows} included records · {result.excludedRows} excluded ({p[2]} filtered; {p[3]} invalid). {t.rows.length?'Visible dates: '+t.rows[0][0]+' – '+t.rows[t.rows.length-1][0]: 'No matching dates'}. Filters: {params.search||'all dates'}; workspace {params.workspace||'all'}.</p>
 {data.length?<LineChart data={data} options={options}/>:<p role="status">No valid records match these filters.</p>}
 <div aria-label="Analytical caveats">{result.warnings.map((x,i)=><p key={i}>{x}</p>)}<p>Blank or invalid dates and blank, negative, noninteger or nonfinite user counts are excluded. No deduplication; record counts are not distinct people. Missing workspace IDs are retained under All workspaces. Signups are not plotted.</p><p>Source revision: {p[0]}. Refresh timestamp unavailable. Date checks use {p[4]} UTC.</p></div>
 {t.rows.length>0&&<details><summary>Daily values and workspace coverage</summary><div style={{overflowX:'auto'}}><Table size="sm" aria-label="Daily reported users and record coverage"><TableHead><TableRow>{['Date','Users ('+p[1]+')','Records','Workspace IDs'].map(h=><TableHeader key={h}>{h}</TableHeader>)}</TableRow></TableHead><TableBody>{t.rows.map(r=><TableRow key={String(r[0])}>{r.map((x,i)=><TableCell key={i}>{i===1?Number(x).toLocaleString(undefined,{maximumFractionDigits:2}):String(x)||'(missing)'}</TableCell>)}</TableRow>)}</TableBody></Table></div></details>}
 </section>;
}

