export function checks(result,ctx){
 const s=ctx.sources.find(x=>x.id==='1c3f83a2-fb7c-4a76-91f3-2175eefe7a5b');if(!s)return [{name:'Required source exists',passed:false}];
 const idx=id=>s.columns.findIndex(c=>c.id===id),di=idx('c0'),vi=idx('c1'),wi=idx('c3');
 const valid=s.rows.filter(r=>{const date=r[di]||'',raw=(r[vi]||'').trim(),n=Number(raw);if(!date.toLowerCase().includes(String(ctx.params.search||'').toLowerCase())||(ctx.params.workspace&&r[wi]!==ctx.params.workspace))return false;const dt=new Date(date+'T00:00:00Z');return /^\d{4}-\d{2}-\d{2}$/.test(date)&&!isNaN(dt.getTime())&&dt.toISOString().slice(0,10)===date&&raw!==''&&Number.isFinite(n)&&n>=0&&Math.floor(n)===n;});
 const dates=[...new Set(valid.map(r=>r[di]))].sort();const actual=result.datasets.daily.rows;
 const correct=dates.length===actual.length&&dates.every((date,i)=>{const subset=valid.filter(r=>r[di]===date);let expected=subset.reduce((n,r)=>n+Number(r[vi]),0);if(ctx.params.aggregation==='average')expected/=subset.length;return actual[i][0]===date&&Math.abs(actual[i][1]-expected)<=1e-9*Math.max(1,Math.abs(expected))&&actual[i][2]===subset.length&&actual[i][3]===[...new Set(subset.map(r=>r[wi]||''))].sort().join(', ');});
 return [{name:'Input and exclusion counts independently reconciled',passed:result.inputRows===s.rows.length&&result.includedRows===valid.length&&result.excludedRows===s.rows.length-valid.length},{name:'Daily values and workspace coverage independently recomputed',passed:correct},{name:'Finite nonnegative user values',passed:actual.every(r=>Number.isFinite(r[1])&&r[1]>=0)},{name:'Workspace identifiers preserved exactly',passed:JSON.stringify(result.datasets.workspaces.rows)===JSON.stringify([...new Set(s.rows.map(r=>r[wi]||'').filter(Boolean))].sort().map(x=>[x]))}];
}
